// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2015, "4-5", [{"author":"Л. Фёдорова","question":"В слове <em>едва</em> «спряталась» цифра. А в каком из названий цветов «спрятался» волшебник?","choices":["<em>василёк</em>","<em>гладиолус</em>","<em>левкой</em>","<em>магнолия</em>","<em>хризантема</em>."],"key":"Г","review":["Волшебник в названии","В слове «едва» слово «два» находится целиком внутри. Так же ищи короткое слово, означающее волшебника.","В «магнолия» первые три буквы образуют «маг». Это и есть спрятанный волшебник."]},{"author":"Б. Иомдин","question":"Какое слово связано с погодой?","choices":["<em>разоблачить</em>","<em>тучный</em>","<em>дождаться</em>","<em>ограда</em>","<em>ненастье</em>."],"key":"Д","review":["Какое слово о погоде","Сравни значения. «Тучный» значит, например, «полный» или «плодородный», «дождаться» — ждать до нужного момента, «разоблачить» — раскрыть обман.","«Ненастье» означает плохую погоду, например с дождём и сильным ветром. «Ограда» — забор, так что подходит «ненастье»."]},{"author":"С. Переверзева","question":"— Вы всё ещё гуляете? — воскликнула маленькая Полина, увидев Лёву с мамой на детской площадке поздно вечером. — Я думала, это мы одни такие <em>ночники</em>. А как надо было сказать?","choices":["так и надо было","<em>вечерники</em>","<em>полуночники</em>","<em>подвечерники</em>","<em>припоздняшки</em>."],"key":"В","review":["Вечерняя прогулка","Дети всё ещё гуляют поздно вечером. Ищи слово про тех, кто долго не ложится спать.","«Полуночник» — человек, который бодрствует допоздна. «Ночник» обычно так называют маленький светильник."]},{"author":"И. Леенсон","question":"Кто из этих животных пасётся?","choices":["волк","собака","мышь","змея","лошадь."],"key":"Д","review":["Кто на пастбище","Пастись — кормиться травой или другой растительностью на пастбище. Сравни, кто из списка так добывает корм.","Лошадь может пастись на лугу и щипать траву. Волк, собака, мышь и змея в обычной речи не пасутся."]},{"author":"С. Бурлак","question":"В какой паре подчёркнутые слова читаются по-разному?","choices":["<em>на</em> <em><u>реке</u></em> <em>— по</em> <em><u>реке</u></em>","<em>с</em> <em><u>поля</u></em> <em>— на</em> <em><u>поля</u></em>","<em>с</em> <em><u>ветками</u></em> <em>— под</em> <em><u>ветками</u></em>","<em>на</em> <em><u>лошади</u></em> <em>— с</em> <em><u>лошади</u></em>","<em>на</em> <em><u>кролика</u></em> <em>— без</em> <em><u>кролика</u></em>."],"key":"Б","review":["Чтение одинаковых форм","Сравни «с по́ля», то есть с одного поля, и «на поля́», то есть на несколько полей. Слово написано одинаково, но его ударение меняется.","Во всех остальных парах ударение остаётся на месте: реке́, ве́тками, ло́шади, кро́лика. Различается чтение только у «по́ля — поля́»."]},{"author":"А. Иткин","question":"Какая буква может стоять после буквы <strong><em>щ</em></strong>?","choices":["<em>ъ</em>","<em>ы</em>","<em>ь</em>","<em>э</em>","ни одна из перечисленных стоять не может."],"key":"В","review":["Буква после щ","Ищи реальное слово, в котором после щ стоит одна из предложенных букв. Вспомни, например, «вещь», «помощь», «ночной плащ».","В «вещь» и «помощь» сразу за щ стоит ь. Такой пример показывает, что мягкий знак после щ возможен."]},{"author":"Е. Муравенко","question":"Когда человеку неловко в незнакомой ситуации, говорят, что <em>он чувствует себя не</em> <em>в</em> <em>своей</em> …","choices":["<em>квартире</em>","<em>семье</em>","<em>тарелке</em>","<em>чашке</em>","<em>ложке</em>."],"key":"В","review":["В незнакомой ситуации","Человеку неловко и не по себе. Нужно достроить устойчивое выражение «не в своей …».","Обычно говорят «не в своей тарелке». Это выражение можно употребить в гостях или в любой непривычной обстановке."]},{"author":"А. Сомин","question":"Полотно по-белорусски называется <em>палатно</em>. А что по-белорусски называется <em>нагавіцы</em>? (Белорусское <em>і</em> читается как русское <em>и.</em>)","choices":["штаны","варежки","рукава","наушники","очки."],"key":"А","review":["Предмет по-белорусски","В паре «полотно — палатно» русскому о соответствует белорусское а. Начало «наг-» может соответствовать русскому «ног-».","Слово связано с ногами. Из предложенных вещей именно штаны надевают на ноги."]},{"author":"Б. Иомдин","question":"Как не говорят?","choices":["<em>клубничина</em>","<em>черничина</em>","<em>маличина</em>","<em>брусничина</em>","<em>земляничина</em>."],"key":"В","review":["Одна ягода","В «клубничина», «черничина», «брусничина», «земляничина» меняется к на ч перед добавленным «-ин-». Так называют одну ягоду.","Слово «малина» устроено иначе и не оканчивается на «-ика». «Маличина» не употребляется. Можно сказать «ягода малины» или «малинка»."]},{"author":"Е. Бикмаев","question":"Что означает встречающееся в некоторых русских говорах слово <em>льзя</em>?","choices":["‘нужно’","‘можно’","‘невозможно’","‘запрещено’","‘обязательно’."],"key":"Б","review":["Диалектное слово","Сравни «льзя» и знакомое «нельзя». В начале «нельзя» слышится отрицание «не-».","Убери отрицание, и запрет превратится в разрешение. «Льзя» значит «можно»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"<em>В его голосе Миша услышал желание получить утвердительный ответ</em> (Анатолий Рыбаков). А что такое утвердительный ответ?","choices":["уверенный ответ","убедительный ответ","правдивый ответ","ответ «да»","ответ «нет»."],"key":"Г","review":["Какого ответа ждут","Сравни слова «утвердительный» и «отрицательный». Первое подтверждает то, о чём спрашивают, а второе отрицает.","Когда на вопрос «Ты согласен?» говорят «да», это утвердительный ответ. «Нет» было бы отрицательным."]},{"author":"И. Иткин","question":"Какое из этих слов в современном русском языке <strong>не</strong> образовано от слова женского рода?","choices":["<em>вилка</em>","<em>чашка</em>","<em>шубка</em>","<em>мышка</em>","<em>башенка</em>."],"key":"А","review":["Исходный род слова","Найди исходные слова: «чашка» от «чаша», «шубка» от «шуба», «мышка» от «мышь», «башенка» от «башня». Ко всем подходит слово «она».","«Вилка» связана со словом «вилы». Оно употребляется только во множественном числе и в современном языке не относится к женскому роду."]},{"author":"Л. Фёдорова","question":"Ребёнка, которому исполнился год, называют годовалым. Какое из прилагательных образовано с помощью «полутора-» и основы именно этого слова?","choices":["<em>полуторагодичный</em>","<em>полуторагодовалый</em>","<em>полуторагодовой</em>","<em>полуторагодный</em>","<em>полуторалетний</em>."],"key":"Б","unrated":false,"reviewedEdition":true,"review":["Возраст Васи","У слова «годовалый» убери окончание -ый. Получится основа «годовал-».","Прибавь спереди «полутора-» и верни окончание: «полуторагодовалый». Слово «полуторалетний» тоже обозначает возраст, но в нём другая основа."]},{"author":"А. Пиперски","question":"В каком месяце могла быть опубликована газетная заметка «В Самарской области начался ледостав»?","choices":["в марте","в апреле","в июне","в августе","в ноябре."],"key":"Д","review":["Начало ледостава","Разбери слово «ледостав». Оно связано со льдом, который образует неподвижный покров на водоёме.","В Самарской области водоёмы начинают замерзать с наступлением холодов. Из перечисленных месяцев ближе всего к этому времени ноябрь, когда и могла выйти заметка о начале ледостава."]},{"author":"А. Пиперски","question":"Какая из этих форм не может быть родительным падежом?","choices":["<em>вещей</em>","<em>чащей</em>","<em>товарищей</em>","<em>овощей</em>","<em>щей</em>."],"key":"Б","review":["Формы после «нет»","Поставь слова после «нет»: нет вещей, нет товарищей, нет овощей, нет щей. В этих примерах получился родительный падеж.","Про лесную чащу можно сказать «нет чащи» или «нет чащ». «Чащей» отвечает на «чем?», как в «любоваться чащей», и стоит в творительном падеже."]},{"author":"А. Пиперски","question":"Какое из этих слов не относится к человеку?","choices":["<em>гонец</em>","<em>гонитель</em>","<em>гонщик</em>","<em>гончая</em>","<em>изгнанница</em>."],"key":"Г","review":["Слова для людей и животных","Гонец доставляет вести, гонитель преследует кого-то, гонщик участвует в гонках, изгнанница покинула родное место. Все эти слова могут обозначать людей.","«Гончая» — охотничья собака. Она преследует зверя по следу."]},{"author":"П. Аркадьев","question":"Слова <em>дуэт</em>, <em>квартет</em>, <em>квинтет</em>, <em>секстет</em>, <em>соло</em>, <em>трио</em> записаны в алфавитном порядке. Запишем под каждым из них соответствующее ему число. Какой ряд чисел получится?","choices":["1, 2, 3, 4, 5, 6","2, 5, 4, 6, 1, 3","2, 4, 6, 1, 5, 3","2, 4, 5, 3, 1, 6","2, 4, 5, 6, 1, 3."],"key":"Д","review":["Сколько исполнителей","Сопоставь музыкальные слова с количеством участников. Дуэт — двое, квартет — четверо, квинтет — пятеро, секстет — шестеро.","Соло выполняет один, а трио — трое. В исходном алфавитном порядке выходит 2, 4, 5, 6, 1, 3."]},{"author":"Б. Иомдин","question":"В романе Эдварда Резерфорда «Лондон» (перевод Елены Копосовой) читаем, как девочка прогоняла волка:\n<em>— Уходи! Убирайся! — неистово завопила кроха. — Глупая зверюжина! Уматывай! — И, скорчившись, как делала это, когда закатывала истерику дома,</em> <em>буквально взвыла: — Проваливай!</em>\nЕсли бы волк послушался девочку, то как было бы странно про него сказать?","choices":["<em>ушёл</em>","<em>убрался</em>","<em>умотал</em>","<em>провалил</em>","среди ответов (А)‒(Г) нет правильного."],"key":"Г","review":["Как девочка гонит волка","Свяжи команды с действиями. После «уходи» можно сказать «ушёл», после «убирайся» — «убрался», после «уматывай» — «умотал».","«Провалил» обычно означает «не справился», например с экзаменом. Из команды «проваливай» со смыслом «уходи» такая форма обычно не получается."]},{"author":"М. Рубинштейн","question":"В словарях нет глагола <em>очитаться</em>, но в последнее время многие люди его употребляют. А что он значит?","choices":["‘составить отчёт’","‘устать от чтения’","‘неправильно прочитать’","‘прочитать слишком много’","‘увлечься чтением’."],"key":"В","review":["Новый глагол","Сравни «описаться» и «оговориться»: в первом случае ошиблись, когда писали, во втором — когда говорили.","Слово «очитаться» построили по тому же образцу. Оно значит ошибиться при чтении, то есть прочитать что-то неправильно."]},{"author":"И. Иткин","question":"Какое из этих предложений можно понять в двух разных смыслах?","choices":["<em>Всё понятно.</em>","<em>Он на всё согласен.</em>","<em>Ты всё пела?</em>","<em>Всё шутишь?</em>","<em>Всё будет сделано!</em>"],"key":"В","review":["Два смысла слова «всё»","Вопрос «Ты всё пела?» может быть о всех песнях. Тогда «всё» отвечает на вопрос «что ты пела?».","Ещё так можно спросить, пела ли собеседница всё время. В этом случае «всё» означает «постоянно», как во фразе «Всё шутишь?»."]},{"author":"А. Бердичевский","question":"Двухлетний Ян слово <em>теперь</em> произносит как <em>пете́рь</em>, <em>купить</em> — как <em>пуки́ть</em>, а <em>тебя</em> — как <em>педя́</em>. Как Ян произносит слово <em>фазан</em>?","choices":["<em>сава́н</em>","<em>сафа́н</em>","<em>фаса́н</em>","<em>саза́н</em>","<em>фава́н</em>."],"key":"А","review":["Как Ян меняет звуки","«Теперь» превращается в «пете́рь», а «купить» — в «пуки́ть», потому что Ян меняет местами два первых согласных. В паре «тебя — педя́» видно ещё одно правило. На первом месте остаётся глухой звук, на втором — звонкий.","В «фазан» звук [ф] глухой, его произносят губой, а [з] звонкий, его произносят языком у зубов. Меняем место: глухой у зубов — [с], звонкий у губы — [в]. Получается «сава́н»."]},{"author":"П. Аркадьев","question":"Какое слово образовано не так, как другие?","choices":["<em>закалка</em>","<em>скакалка</em>","<em>сушилка</em>","<em>сеялка</em>","<em>мигалка</em>."],"key":"А","review":["Слова на «-лка»","Скакалка нужна, чтобы скакать, сушилка — чтобы сушить, сеялка — чтобы сеять, мигалка — чтобы мигать. Все эти слова называют предметы, в них добавили «-лк-».","«Закалка» — процесс закаливания. В ней л уже была в корне «кал-», а к основе добавили только «-к-»."]},{"author":"Е. Бикмаев","question":"В глаголе <em>п_л_ть</em> пропущены гласные. Сколькими способами можно восстановить глагол, если использовать только гласные <em>а</em>, <em>и</em> и <em>о</em> (можно использовать как две разные гласные, так и две одинаковые)?","choices":["одним","двумя","тремя","четырьмя","пятью."],"key":"Г","review":["Гласные в глаголе","Проверь, какое слово получается при каждом выборе. С концом «-лать» из данных гласных нет обычных глаголов на такую основу.","С концом «-лить» получаются «палить», «пилить» и «полить». С концом «-лоть» есть «полоть». Всего четыре слова."]},{"author":"А. Пиперски","question":"В одной книге, переведённой с английского языка, читаем: «Список начинался с Албании и заканчивался …». Какая страна завершает список?","choices":["Камерун","Лесото","Фиджи","Зимбабве","Марокко."],"key":"Г","review":["Страны в конце списка","Книга переведена с английского. Албания по-английски пишется Albania, так что список может идти по английскому алфавиту от A.","Английские начала других названий: Cameroon, Fiji, Lesotho, Morocco, Zimbabwe. Последней стоит страна на Z — Зимбабве."]},{"author":"С. Бурлак","question":"Какое из слов может в единственном числе стоять после предлога <em>из</em> в двух разных формах?","choices":["<em>лес</em>","<em>река</em>","<em>ручей</em>","<em>роща</em>","<em>чаща</em>."],"key":"А","review":["Две формы после «из»","Произнеси сочетания «из реки», «из ручья», «из рощи», «из чащи». У каждого из этих слов обычно одна форма после «из».","Можно сказать «вышел из леса» и «вышел из лесу». У слова «лес» после «из» встречаются окончания «-а» и «-у»."]},{"author":"И. Иткин","question":"Какой из этих глаголов реже остальных сочетается с подлежащим в единственном числе?","choices":["<em>выкупить</em>","<em>закупить</em>","<em>накупить</em>","<em>подкупить</em>","<em>раскупить</em>."],"key":"Д","review":["Кто совершает покупку","Одному человеку легко выкупить билет, закупить продукты, накупить сладостей или подкупить кого-то. Представь, что товар исчезает, потому что его купили.","В выражении «все билеты раскупили» обычно имеется в виду много покупателей. Поэтому «раскупить» реже сочетается с подлежащим в единственном числе."]},{"author":"А. Пиперски","question":"Даны два русских слова, закодированных так, как это делается в общераспространённой компьютерной кодировке Юникод:\n<em>баня:</em> 1073 – 1072 – 1085 – 1103,\n<em>дождь:</em> 1076 – 1086 – 1078 – 1076 – 1100.\nКак расшифровывается слово 1088 – 1105 – 1074?","choices":["<em>ров</em>","<em>сев</em>","<em>рёв</em>","<em>рыб</em>","<em>ряд</em>."],"key":"В","review":["Слова в Юникоде","От кода 1072 для а буквы идут по алфавиту без ё. Поэтому для в получаем 1072 + 2 = 1074, а для р — 1072 + 16 = 1088. Ищи вариант, который начинается на р и заканчивается на в.","Таких вариантов два — «ров» и «рёв». В примере «дождь» буква о уже имеет код 1086, а нам нужен код 1105. Значит, средняя буква — ё, и получается «рёв»."]},{"author":"Е. Ренковская","question":"Каким глаголом можно продолжить ряд глаголов: <em>молоть, пороть, нести,</em> …?","choices":["<em>рубить</em>","<em>полоть</em>","<em>городить</em>","<em>сеять</em>","<em>есть</em>."],"key":"В","review":["Глаголы в выражениях","Составь привычные фразы: «молоть чепуху», «пороть чушь», «нести вздор». Во всех случаях говорят о бессмысленных словах.","Так же говорят «городить ерунду». Глагол «городить» продолжает этот ряд."]},{"author":"Б. Иомдин","question":"Перед вами — стихотворение Валерия Брюсова «Запоздалый ответ»:\nВЛЕКИ СУРОВУЮ МЕЧТУ,\nДАЙ УТОМЛЁННОЙ РЕЧИ,\nВАДИМ, И ЭТУ ДАЛЬ И ТУ,\nДАРИ НА СТАРОМ ВЕЧЕ\nСЕБЕ МГНОВЕНИЕ ОГНЯ,\nДАЙ СМУТЕ СТЕНЫ ВОЛИ.\nТЫ ИСКУШЕНИЕ КРЕМНЯ:\nЗАТМЕНИЕ, ОШИБКУ ДНЯ —\nТРОНЬ ИСКРОЮ ДО БОЛИ!\nКому из поэтов оно посвящено?","choices":["Вадиму Шефнеру","Вадиму Шершеневичу","Вадиму Гарднеру","Вадиму Баяну","Вадиму Левину."],"key":"Б","review":["Стихотворение Брюсова","Считай буквы без пробелов и знаков. В первой строке возьми первую слева, во второй — вторую слева, и так до девятой. Получится «ВАДИМУШЕР».","Пойди обратно с восьмой строки: возьми восьмую букву справа, в седьмой — седьмую справа и так до первой. Получится «ШЕНЕВИЧУ». Вместе читается «Вадиму Шершеневичу»."]},{"author":"М. Рубинштейн","question":"Персонажи сказки итальянского писателя Джанни Родари «Приключения Чиполлино» ― фрукты и овощи. Перед вами названия нескольких глав из неё по-итальянски и их буквальные переводы. Имена некоторых персонажей пропущены.\n1. Schiaccia un piede … al gran principe Limone\n(… отдавил ногу великому принцу Лимону).\n2. Come fu che il sor … fabbricò la sua casina\n(Как вышло, что господин … построил себе домик).\n3. Il terribile cane Mastino è preso per sete da …\n(Ужасного пса Мастино спасает от жажды …).\n4. Il barone …, con Fagiolone porta-pancia\n(Барон … с Фасолинкой, носильщиком живота).\n5. Topo-in-capo perde il decoro, mentre esulta …\n(Мышь-командир теряет достоинство, тем временем ликует …).\nА вот пропущенные имена в перепутанном порядке: Cipollino (луковка), Cipollone (большая луковица), Melarancia (апельсин), Zucchina (кабачок), Pomodoro (помидор). Ответьте, в каком порядке они стоят в названиях глав. Знакомство со сказкой для этого не обязательно.","choices":["Cipollino, Cipollone, Melarancia, Pomodoro, Zucchina","Zucchina, Pomodoro, Melarancia, Cipollone, Cipollino","Melarancia, Zucchina, Cipollone, Pomodoro, Cipollino","Cipollone, Cipollino, Zucchina, Pomodoro, Melarancia","Cipollone, Zucchina, Cipollino, Melarancia, Pomodoro."],"key":"Д","review":["Главы «Чиполлино»","Ищи похожие концы слов в итальянских заголовках. Limone рифмуется с Cipollone, casina с Zucchina, Mastino с Cipollino.","К porta-pancia подходит Melarancia, к decoro — Pomodoro. Так восстанавливаются все пять имён по порядку."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
